#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>
#include <errno.h>
#include <float.h>

/* Version */
#define PROJ_RELEASE "Rel. 9.9.0, September 15th, 2026"

/* Math constants */
#ifndef M_PI
#define M_PI 3.14159265358979323846264338327950288
#endif
#define DEG_TO_RAD (M_PI/180.0)
#define RAD_TO_DEG (180.0/M_PI)
#define HUGE_ERROR 1e30

/* Error codes */
#define PROJ_ERR_NONE 0
#define PROJ_ERR_INVALID_LAT 2
#define PROJ_ERR_UNKNOWN_PROJ 1027

/* Forward declarations */
typedef struct ProjParams ProjParams;
typedef int (*FwdFunc)(ProjParams*, double lon, double lat, double *x, double *y);
typedef int (*InvFunc)(ProjParams*, double x, double y, double *lon, double *lat);

/* Ellipsoid parameters */
typedef struct {
    double a;    /* semi-major axis */
    double b;    /* semi-minor axis */  
    double f;    /* flattening = (a-b)/a */
    double es;   /* eccentricity squared = 2f - f^2 */
    double e;    /* eccentricity = sqrt(es) */
    double n;    /* third flattening = (a-b)/(a+b) */
    double one_es;  /* 1 - es */
    double rone_es; /* 1 / (1 - es) */
} Ellps;

/* Projection parameters */
struct ProjParams {
    char   name[64];      /* projection name */
    Ellps  ellps;         /* ellipsoid */
    double lon_0;         /* central meridian (radians) */
    double lat_0;         /* latitude of origin (radians) */
    double lat_1;         /* standard parallel 1 (radians) */
    double lat_2;         /* standard parallel 2 (radians) */
    double lat_ts;        /* latitude of true scale (radians) */
    double k0;            /* scale factor */
    double x_0;           /* false easting (m) */
    double y_0;           /* false northing (m) */
    double to_meter;      /* units to meter conversion */
    double fr_meter;      /* meter to units conversion */
    int    zone;          /* UTM zone */
    int    south;         /* UTM south hemisphere */
    int    approx;        /* approx flag */
    int    is_spherical;  /* use spherical formulas */
    int    err;           /* error code */
    char   errmsg[256];   /* error message */

    /* Derived quantities for specific projections */
    double n;    /* cone constant for conic projections */
    double c;    /* auxiliary constant */
    double rho0; /* rho at lat_0 */
    double ml0;  /* meridional length at lat_0 */

    /* function pointers */
    FwdFunc fwd;
    InvFunc inv;

    /* Private data for complex projections */
    double par[16];

    /* For UTM/TM */
    double Mc[5]; /* Meridian arc coefficients */

    /* Free function */
    void (*pfree)(struct ProjParams*);
};

/* ===================================================================
 * MATH UTILITIES
 * =================================================================== */

static double atanh_impl(double x) {
    return 0.5 * log((1.0 + x) / (1.0 - x));
}

/* Meridional arc (Bessel series) for ellipsoid */
static double meridional_arc(const Ellps *e, double phi) {
    /* Using series from Snyder */
    double es = e->es;
    double e2 = es;
    double e4 = e2 * e2;
    double e6 = e4 * e2;
    double e8 = e6 * e2;

    double A0 = 1.0 - e2/4.0 - 3.0*e4/64.0 - 5.0*e6/256.0;
    double A2 = 3.0/8.0 * (e2 + e4/4.0 + 15.0*e6/128.0);
    double A4 = 15.0/256.0 * (e4 + 3.0*e6/4.0);
    double A6 = 35.0*e6/3072.0;

    return e->a * (A0*phi - A2*sin(2.0*phi) + A4*sin(4.0*phi) - A6*sin(6.0*phi));
}

/* Isometric latitude */
static double isometric_lat(const Ellps *e, double phi) {
    double e_sin = e->e * sin(phi);
    return log(tan(M_PI/4.0 + phi/2.0) * 
               pow((1.0 - e_sin)/(1.0 + e_sin), e->e/2.0));
}

/* Auxiliary sphere radius */
static double sn(const Ellps *e, double phi) {
    double s = sin(phi);
    return e->a / sqrt(1.0 - e->es * s * s);
}

static double sph_n(const Ellps *e, double phi) {
    double sp = sin(phi);
    return e->a / sqrt(1.0 - e->es * sp * sp);
}

/* Conformal latitude (chi) */
static double conformal_lat(const Ellps *e, double phi) {
    return 2.0 * atan(tan(M_PI/4.0 + phi/2.0) * 
        pow((1.0 - e->e*sin(phi))/(1.0 + e->e*sin(phi)), e->e/2.0)) - M_PI/2.0;
}

/* ===================================================================
 * ELLIPSOID INITIALIZATION
 * =================================================================== */

