static void init_ellps_from_ab(Ellps *e, double a, double b) {
    e->a = a;
    e->b = b;
    e->f = (a - b) / a;
    e->es = 2.0*e->f - e->f*e->f;
    e->e = sqrt(e->es);
    e->n = (a - b) / (a + b);
    e->one_es = 1.0 - e->es;
    e->rone_es = 1.0 / e->one_es;
}

static void init_ellps_from_arf(Ellps *e, double a, double rf) {
    double f = (rf == 0.0) ? 0.0 : 1.0 / rf;
    double b = a * (1.0 - f);
    init_ellps_from_ab(e, a, b);
}

static int find_ellps(const char *name, Ellps *e) {
    for (int i = 0; ellps_table[i].name; i++) {
        if (strcmp(ellps_table[i].name, name) == 0) {
            double a = ellps_table[i].a;
            double rf = ellps_table[i].rf;
            double b  = ellps_table[i].b;
            if (rf > 0)
                init_ellps_from_arf(e, a, rf);
            else if (b > 0)
                init_ellps_from_ab(e, a, b);
            else {
                /* Sphere */
                e->a = a; e->b = a; e->f = 0;
                e->es = 0; e->e = 0; e->n = 0;
                e->one_es = 1; e->rone_es = 1;
            }
            return 1;
        }
    }
    return 0;
}

