        self.n = (a - b) / (a + b) if (a + b) > 0 else 0.0
        self.one_es = 1.0 - self.es
        self.rone_es = 1.0 / self.one_es if self.one_es != 0 else float('inf')

    @classmethod
    def from_a_rf(cls, a, rf):
        if rf == 0:
            return cls(a, a)
        f = 1.0 / rf
        b = a * (1.0 - f)
        return cls(a, b)

    @classmethod
    def from_name(cls, name):
        if name in ELLIPSOIDS:
            a, rf, b, desc = ELLIPSOIDS[name]
            if rf is not None:
                return cls.from_a_rf(a, rf)
            elif b is not None:
                return cls(a, b)
            else:
                return cls(a, a)
        raise ValueError(f"Unknown ellipsoid: {name}")


def get_ellipsoid(params):
    """Get ellipsoid from projection parameters"""
    a = params.get('a')
    b = params.get('b')
    rf = params.get('rf')
    R = params.get('R')
    ellps = params.get('ellps')
    datum = params.get('datum')

    if R is not None:
        R = float(R)
        return Ellipsoid(R, R)

    if a is not None:
        a = float(a)
        if b is not None:
            return Ellipsoid(a, float(b))
        elif rf is not None:
            return Ellipsoid.from_a_rf(a, float(rf))
        else:
            return Ellipsoid(a, a)

    if datum is not None:
        ename = DATUMS.get(datum)
        if ename:
            return Ellipsoid.from_name(ename)

    if ellps is not None:
        return Ellipsoid.from_name(ellps)

    # Default WGS84
    return Ellipsoid.from_name('WGS84')


