def parse_angle(s):
    """Parse an angle string, returning value in radians.
    Formats: decimal degrees, DdM'S", Dd, DdM', with N/S/E/W suffix
    """
    s = s.strip()
    if not s:
        return 0.0

    # Check for radians suffix
    if s.endswith('r') or s.endswith('R'):
        return float(s[:-1])

    # Check for direction suffix
    sign = 1.0
    if s[-1] in ('N', 'n', 'E', 'e'):
        sign = 1.0
        s = s[:-1]
    elif s[-1] in ('S', 's', 'W', 'w'):
        sign = -1.0
        s = s[:-1]

    # Handle negative sign
    if s.startswith('-'):
        sign = -sign
        s = s[1:]

    # Parse DMS format
    # Pattern: degrees[d[minutes['[seconds["]]]]
    if 'd' in s.lower():
        idx = s.lower().index('d')
        deg = float(s[:idx]) if s[:idx] else 0.0
        rest = s[idx+1:]

        mins = 0.0
        secs = 0.0

        if "'" in rest:
            idx2 = rest.index("'")
            mins_str = rest[:idx2]
            mins = float(mins_str) if mins_str else 0.0
            rest2 = rest[idx2+1:]

            if '"' in rest2:
                idx3 = rest2.index('"')
                secs_str = rest2[:idx3]
                secs = float(secs_str) if secs_str else 0.0
            elif rest2:
                secs = float(rest2)
        elif rest:
            mins = float(rest)

        deg_val = deg + mins/60.0 + secs/3600.0
    else:
        deg_val = float(s)

    return sign * deg_val * DEG_TO_RAD


def format_dms(rad, is_lat, dms_places, dms_lead_zeros):
    """Format angle in radians as DMS string"""
    deg_total = rad * RAD_TO_DEG

    if is_lat:
        hemi = 'N' if deg_total >= 0 else 'S'
    else:
        hemi = 'E' if deg_total >= 0 else 'W'

    deg_total = abs(deg_total)
    deg = int(deg_total)
    rem = (deg_total - deg) * 60.0
    mins = int(rem)
    secs = (rem - mins) * 60.0

    # Round to specified decimal places
    if dms_places is None:
        # Default: 3 decimal places, strip trailing zeros
        # Show minimal representation
        secs_rounded = round(secs, 3)
        if secs_rounded >= 60.0:
            secs_rounded = 0.0
            mins += 1
        if mins >= 60:
            mins = 0
            deg += 1

        if secs_rounded == 0.0 and mins == 0:
            return f"{deg}d{hemi}"
        elif secs_rounded == 0.0:
            return f"{deg}d{mins}'{hemi}"
        else:
            # Format with up to 3 decimal places, strip trailing zeros
            secs_str = f"{secs_rounded:.3f}".rstrip('0').rstrip('.')
            return f"{deg}d{mins}'{secs_str}\"{hemi}"
    else:
        fmt = f"{{:.{dms_places}f}}"
        secs_rounded = round(secs, dms_places)
        if secs_rounded >= 60.0:
            secs_rounded = 0.0
            mins += 1
        if mins >= 60:
            mins = 0
            deg += 1

        secs_str = fmt.format(secs_rounded)

        if dms_lead_zeros:
            # With leading zeros
            if dms_places > 0:
                int_part = 2
                secs_str = f"{secs_rounded:0{int_part + 1 + dms_places}.{dms_places}f}"
            else:
                secs_str = f"{int(round(secs_rounded)):02d}"
            mins_str = f"{mins:02d}"
            return f"{deg}d{mins_str}'{secs_str}\"{hemi}"
        else:
            return f"{deg}d{mins}'{secs_str}\"{hemi}"


def format_decimal_degrees(rad, places):
    """Format angle in radians as decimal degrees"""
    deg = rad * RAD_TO_DEG
    return f"{deg:.{places}f}"

