    params = {}
    tokens = proj_str.split()
    for tok in tokens:
        if tok.startswith('+'):
            tok = tok[1:]
        if '=' in tok:
            k, v = tok.split('=', 1)
            params[k] = v
        else:
            params[tok] = ''
    return params

