# ============================================================
# MAIN FUNCTION
# ============================================================

def get_prog_name():
    return os.path.basename(sys.argv[0]) if sys.argv else 'proj'


def print_usage():
    name = get_prog_name()
    print(f"{PROJ_RELEASE}")
    print(f"usage: {name} [-bdeEfiIlmorsStTvVwW [args]] [+opt[=arg] ...] [file ...]")


def print_list(list_type):
    """Print list of projections, ellipsoids, or units"""
    if list_type == 'p':
        # Simple list
        for pname, pdesc, ptype, pparams in PROJECTIONS:
            print(f"{pname} : {pdesc}")
    elif list_type == 'P':
        # Verbose list
        for pname, pdesc, ptype, pparams in PROJECTIONS:
            print(f"{pname} : {pdesc}")
            if ptype:
                print(f"\t{ptype}")
            if pparams:
                print(f"\t{pparams}")
    elif list_type == 'e':
        # Ellipsoids
        for name, (a, rf, b, desc) in ELLIPSOIDS.items():
            if rf is not None:
                print(f"{name:>10} a={a:<15} rf={rf:<17} {desc}")
            else:
                print(f"{name:>10} a={a:<15} b={b:<17} {desc}")
    elif list_type == 'u':
        # Units
        for name, factor, desc in UNITS:
            print(f"{name:>25} {factor:<22} {desc}")
    else:
        name = get_prog_name()
        print(f"{PROJ_RELEASE}", file=sys.stderr)
        print(f"<{name}>: ", file=sys.stderr)
        print(f"invalid list option: l{list_type}", file=sys.stderr)
        print(f"program abnormally terminated", file=sys.stderr)
        sys.exit(1)


def proj_error_exit(msg, cause=None, exit_code=3):
    """Print error and exit"""
    name = get_prog_name()
    print(f"{PROJ_RELEASE}", file=sys.stderr)
    print(f"<{name}>: ", file=sys.stderr)
    print(f"{msg}", file=sys.stderr)
    if cause:
        print(f"cause: {cause}", file=sys.stderr)
    print(f"program abnormally terminated", file=sys.stderr)
    sys.exit(exit_code)


def build_proj_from_epsg(epsg_str):
    """Build projection from EPSG string"""
    if epsg_str.upper().startswith('EPSG:'):
        code = int(epsg_str[5:])
    else:
        code = int(epsg_str)

    info = EPSG_DB.get(code)
    if info is None:
        # Unknown EPSG
        print(f"proj_create: unrecognized format / unknown name", file=sys.stderr)
        proj_error_exit("projection initialization failure", "Unknown error (code 2)")

    if info.get('_geographic', False):
        proj_error_exit("CRS must be projected")

    if info.get('_is_pipeline', False):
        fwd_params = info.get('_fwd_params', {})
        axisswap = info.get('_axisswap', False)
        fwd_proj_name = info.get('_fwd_proj', 'tmerc')
        fwd_params['proj'] = fwd_proj_name
        fwd_p = make_projection(fwd_params)
        return PipelineProjection(fwd_p, axisswap), info, fwd_params

    params = dict(info)
    # Remove internal keys
    params = {k: v for k, v in params.items() if not k.startswith('_')}

    return make_projection(params), info, params


def run_projection(proj, params, opts, infile, outfile):
    """Run projection on input, writing to output"""
    is_inverse = opts.get('inverse', False)
    swap_input = opts.get('swap_input', False)
    swap_output = opts.get('swap_output', False)
    binary_in = opts.get('binary_in', False)
    binary_out = opts.get('binary_out', False)
    fmt = opts.get('fmt', None)
    decimal_places = opts.get('decimal_places', None)
    multiplier = opts.get('multiplier', 1.0)
    error_string = opts.get('error_string', '*\t*')
    scale_factors_flag = opts.get('scale_factors', False)
    verbose_V = opts.get('verbose_V', False)
    verbose_v = opts.get('verbose_v', False)
    echo_input = opts.get('echo_input', False)
    dms_places = opts.get('dms_places', None)
    dms_lead_zeros = opts.get('dms_lead_zeros', False)
    tag = opts.get('tag', None)

    # Unit conversion factor for output
    to_meter = getattr(proj, 'to_meter', 1.0)

    while True:
        if binary_in:
            data = infile.buffer.read(16)
            if not data:
                break
            if len(data) < 16:
                break
            x_in, y_in = struct.unpack('dd', data)
            # Binary input is always in radians
            if swap_input:
                x_in, y_in = y_in, x_in
            extra = ''
            line = None
        else:
            line = infile.readline()
            if not line:
                break
            line = line.rstrip('\n').rstrip('\r')

            # Check for comment line
            if line.startswith('#'):
                print(line)
                continue

            # Check tag
            if tag is not None:
                first_token = line.split()[0] if line.split() else ''
                if first_token != tag:
                    print(f"{PROJ_RELEASE}", file=sys.stderr)
                    print(f"<{get_prog_name()}>: ", file=sys.stderr)
                    print(f"missing -t col. 1 tag", file=sys.stderr)
                    print(f"program abnormally terminated", file=sys.stderr)
                    sys.exit(1)
                # Skip the tag token
                line = line[len(tag):].lstrip()

            # Parse coordinates
            x_in, y_in, extra, status = parse_input_line(line, swap_input)

            if status == 'extra' and x_in == 0.0 and y_in == 0.0:
                # Non-parseable start - treat as coordinates 0,0 with extra
                pass

        # Perform projection
        try:
            if is_inverse:
                # x_in, y_in are in projection units (need unit conversion)
                if not binary_in:
                    xi = x_in / to_meter
                    yi = y_in / to_meter
                else:
                    xi = x_in
                    yi = y_in

                if isinstance(proj, PipelineProjection):
                    lon_out, lat_out = proj.inverse(xi, yi)
                else:
                    lon_out, lat_out = proj.inverse(xi, yi)
                error = False
            else:
                # x_in, y_in are geographic (radians)
                if isinstance(proj, PipelineProjection):
                    x_out, y_out = proj.forward(x_in, y_in)
                else:
                    x_out, y_out = proj.forward(x_in, y_in)
                # Apply unit conversion
                x_out = x_out / to_meter
                y_out = y_out / to_meter
                error = False
        except ProjectionError as ex:
            print(ex.proj_msg, file=sys.stderr)
            error = True
        except Exception as ex:
            print(str(ex), file=sys.stderr)
            error = True

        if binary_out:
            if error:
                outfile.buffer.write(struct.pack('dd', float('inf'), float('inf')))
            else:
                if is_inverse:
                    outfile.buffer.write(struct.pack('dd', lon_out, lat_out))
                else:
                    outfile.buffer.write(struct.pack('dd', x_out * to_meter, y_out * to_meter))
            continue

        if error:
            if echo_input and not binary_in:
                orig = line if line else ''
                print(f"{orig}\t{error_string}{' ' + extra if extra else ''}")
            else:
                out_str = error_string
                if extra:
                    out_str += ' ' + extra
                print(out_str)
            continue

        if is_inverse:
            # Compute scale factors if needed
            if scale_factors_flag or verbose_V:
                sf = compute_scale_factors(proj.fwd_proj if isinstance(proj, PipelineProjection) else proj, lon_out, lat_out)

            out = format_output(lon_out, lat_out, fmt, decimal_places, swap_output,
                               dms_places, dms_lead_zeros, is_inverse=True, multiplier=multiplier)

            if verbose_V and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                print_verbose(proj, params, '', lon_out, lat_out, 
                             lon_out, lat_out, h, k, s, omega, conv, a_tis, b_tis)

            if scale_factors_flag and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                out = format_scale_output(lon_out, lat_out, h, k, s, omega, conv, a_tis, b_tis,
                                         fmt=None, decimal_places=decimal_places,
                                         multiplier=multiplier)
        else:
            # Compute scale factors if needed
            if scale_factors_flag or verbose_V:
                sf = compute_scale_factors(proj.fwd_proj if isinstance(proj, PipelineProjection) else proj, x_in, y_in)

            out = format_output(x_out, y_out, fmt, decimal_places, swap_output,
                               dms_places, dms_lead_zeros, is_inverse=False, multiplier=multiplier)

            if verbose_V and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                print_verbose(proj, params, '', x_in, y_in,
                             x_out, y_out, h, k, s, omega, conv, a_tis, b_tis)

            if scale_factors_flag and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                out = format_scale_output(x_out, y_out, h, k, s, omega, conv, a_tis, b_tis,
                                         fmt=fmt, decimal_places=decimal_places,
                                         multiplier=multiplier, extra=extra)
                if extra and not scale_factors_flag:
                    out += ' ' + extra
            elif extra:
                out += ' ' + extra

        if echo_input and not binary_in and not is_inverse:
            # Get original input string
            orig_parts = line.split()[:2] if line else ['0', '0']
            orig = ' '.join(orig_parts[:2])
            print(f"{orig}\t{out}")
        elif echo_input and not binary_in and is_inverse:
            out_xy = f"{x_in/to_meter:.2f} {y_in/to_meter:.2f}"
            print(f"{out_xy}\t{out}")
        else:
            print(out)


