                orig = line if line else ''
                print(f"{orig}\t{error_string}{' ' + extra if extra else ''}")
            else:
                out_str = error_string
                if extra:
                    out_str += ' ' + extra
                print(out_str)
            continue

        if is_inverse:
            # Compute scale factors if needed
            if scale_factors_flag or verbose_V:
                sf = compute_scale_factors(proj.fwd_proj if isinstance(proj, PipelineProjection) else proj, lon_out, lat_out)

            out = format_output(lon_out, lat_out, fmt, decimal_places, swap_output,
                               dms_places, dms_lead_zeros, is_inverse=True, multiplier=multiplier)

            if verbose_V and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                print_verbose(proj, params, '', lon_out, lat_out, 
                             lon_out, lat_out, h, k, s, omega, conv, a_tis, b_tis)

            if scale_factors_flag and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                out = format_scale_output(lon_out, lat_out, h, k, s, omega, conv, a_tis, b_tis,
                                         fmt=None, decimal_places=decimal_places,
                                         multiplier=multiplier)
        else:
            # Compute scale factors if needed
            if scale_factors_flag or verbose_V:
                sf = compute_scale_factors(proj.fwd_proj if isinstance(proj, PipelineProjection) else proj, x_in, y_in)

            out = format_output(x_out, y_out, fmt, decimal_places, swap_output,
                               dms_places, dms_lead_zeros, is_inverse=False, multiplier=multiplier)

            if verbose_V and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                print_verbose(proj, params, '', x_in, y_in,
                             x_out, y_out, h, k, s, omega, conv, a_tis, b_tis)

            if scale_factors_flag and sf:
                h, k, s, omega, conv, a_tis, b_tis = sf
                out = format_scale_output(x_out, y_out, h, k, s, omega, conv, a_tis, b_tis,
                                         fmt=fmt, decimal_places=decimal_places,
                                         multiplier=multiplier, extra=extra)
                if extra and not scale_factors_flag:
                    out += ' ' + extra
            elif extra:
                out += ' ' + extra

        if echo_input and not binary_in and not is_inverse:
            # Get original input string
            orig_parts = line.split()[:2] if line else ['0', '0']
            orig = ' '.join(orig_parts[:2])
            print(f"{orig}\t{out}")
        elif echo_input and not binary_in and is_inverse:
