def main():
    argv = sys.argv
    args = argv[1:]

    if not args:
        print_usage()
        sys.exit(0)

    opts = parse_args(args)

    # Handle list options
    if opts.get('list') is not None:
        print_list(opts['list'])
        sys.exit(0)

    # Build the projection
    proj_params = opts['proj_params']
    epsg = opts.get('epsg')

    if not proj_params and not epsg:
        print_usage()
        sys.exit(0)

    # Get projection name for verbose output
    proj = None
    proj_str_parts = []

    try:
        if epsg:
            # EPSG code
            proj, epsg_info, proj_params = build_proj_from_epsg(epsg)
        else:
            # +proj= style
            if 'proj' not in proj_params:
                print(f"proj_create: unrecognized format / unknown name", file=sys.stderr)
                proj_error_exit("projection initialization failure", "Unknown error (code 2)")

            proj_name = proj_params['proj']

            if proj_name in ANGULAR_OUTPUT_PROJS:
                proj_error_exit("can't initialize operations that produce angular output coordinates")

            # Check for non-angular input in inverse mode with angular-output projs
            if opts.get('inverse') and proj_name in ('utm', 'tmerc', 'merc', 'lcc', 'stere',
                                                       'aea', 'laea', 'eqc', 'webmerc', 'etmerc',
                                                       'moll', 'sinu', 'ortho', 'gnom', 'mill',
                                                       'cass', 'poly', 'bonne', 'eqdc'):
                pass  # inverse mode is fine for these

            # Check for +init= (old style)
            if 'init' in proj_params:
                init_val = proj_params['init']
                if init_val.upper().startswith('EPSG:'):
                    # Check if this creates an angular CRS
                    code = int(init_val[5:])
                    info = EPSG_DB.get(code)
                    if info and not info.get('_geographic', False):
                        # Non-geographic - error for +init with proj tool
                        pass
                proj_error_exit("can't initialize operations that take non-angular input coordinates. Try cct.")

            proj = make_projection(proj_params)
    except ProjectionError as ex:
        if ex.code == 3 or 'angular output' in str(ex):
            proj_error_exit(str(ex))
        elif ex.code == 1027:
            print(f"proj_create: Error 1027 (Invalid value for an argument): {ex}", file=sys.stderr)
            proj_error_exit("projection initialization failure", "Invalid value for an argument")
        else:
            proj_error_exit(str(ex))
    except Exception as ex:
        print(f"proj_create: unrecognized format / unknown name", file=sys.stderr)
        proj_error_exit("projection initialization failure", str(ex))

    # Print verbose header if -v or -V
    if opts.get('verbose_v') or opts.get('verbose_V'):
        pname = proj_params.get('proj', '')
        pdesc = ''
        ptype = ''
        pparams_str = ''
        for p in PROJECTIONS:
            if p[0] == pname:
                pdesc = p[1]
                ptype = p[2] or ''
                pparams_str = p[3] or ''
                break
        if pdesc:
            print(f"#{pdesc}")
        if ptype:
            print(f"#\t{ptype}")
        if pparams_str:
            print(f"#\t{pparams_str}")
        # Build proj string
        parts = []
        for k, v in proj_params.items():
            if k.startswith('_'):
                continue
            if v:
                parts.append(f"+{k}={v}")
            else:
                parts.append(f"+{k}")
        parts.append('+break_cs2cs_recursion')
        print(f"# {' '.join(parts)}")

    # Process input
    files = opts.get('files', [])

    if files:
        for fname in files:
            try:
                with open(fname, 'r') as f:
                    run_projection(proj, proj_params, opts, f, sys.stdout)
            except IOError as ex:
                print(f"Error opening {fname}: {ex}", file=sys.stderr)
                sys.exit(1)
    else:
        run_projection(proj, proj_params, opts, sys.stdin, sys.stdout)


if __name__ == '__main__':
    main()

